import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.BtMaDljG.js";var i=JSON.parse(`{"title":"Field Action Status Checker","description":"","frontmatter":{"prev":{"text":"Current Entry as Saved","link":"/documentation/field-types/advance/current-entry-as-saved"},"next":{"text":"Next Excel Entry Exists","link":"/documentation/field-types/advance/next-excel-entry-exists"}},"headers":[],"relativePath":"documentation/field-types/advance/field-action-status-checker.md","filePath":"documentation/field-types/advance/field-action-status-checker.md","lastUpdated":0}`),a={name:`documentation/field-types/advance/field-action-status-checker.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r('<h1 id="field-action-status-checker" tabindex="-1">Field Action Status Checker <a class="header-anchor" href="#field-action-status-checker" aria-label="Permalink to “Field Action Status Checker”">​</a></h1><p>The <strong>Field Action Status Checker</strong> field type evaluates the execution outcome, boolean status, and status messages of previously executed fields within the active form or workflow.</p><p>By defining multi-condition logic with comparison operators and logical grouping, this field type acts as a conditional decision gate. If the configured conditions match, it returns <strong>Success</strong>; otherwise, it returns <strong>Error</strong>, allowing you to trigger customized <a href="/documentation/form-fields/field-response-action.html">Field Response Actions</a>.</p><img src="/image/field-action-status-checker-01.png" alt="Field Action Status Checker Interface" style="max-width:100%;border-radius:8px;margin:16px 0;"><hr><h2 id="overview" tabindex="-1">Overview &amp; Execution Model <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview &amp; Execution Model”">​</a></h2><p>During form automation, every field that executes generates an internal status (<code>true</code> for success, <code>false</code> for failure) and an associated status message.</p><p>The <strong>Field Action Status Checker</strong> lets you query these past outcomes:</p><table tabindex="0"><thead><tr><th>Evaluated Condition Result</th><th>Return Status</th><th>Triggered Channel</th></tr></thead><tbody><tr><td><strong>All conditions match (Evaluates to True)</strong></td><td><strong>Success</strong></td><td>Executes configured <strong>Field Success Response Action</strong></td></tr><tr><td><strong>Conditions do not match (Evaluates to False)</strong></td><td><strong>Error</strong></td><td>Executes configured <strong>Field Error Response Action</strong></td></tr></tbody></table><hr><h2 id="status-check-conditions" tabindex="-1">Status Check Conditions Configuration <a class="header-anchor" href="#status-check-conditions" aria-label="Permalink to “Status Check Conditions Configuration”">​</a></h2><p>Click the blue <strong><code>+</code></strong> button in the header of the <strong>Status Check Conditions</strong> table to add one or more condition evaluation rows:</p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>FIELD NAME</strong></td><td>Text Input</td><td>The exact label or name of the target field to inspect from earlier in the form sequence.</td></tr><tr><td><strong>COMP</strong></td><td>Dropdown</td><td>The comparison operator (<code>==</code> or <code>!=</code>).</td></tr><tr><td><strong>STATUS</strong></td><td>Dropdown</td><td>Target boolean status to verify (<code>true</code>, <code>false</code>, or <code>- Status</code> to omit).</td></tr><tr><td><strong>MESSAGE</strong></td><td>Text Input</td><td>Expected status message or substring generated by the field action.</td></tr><tr><td><strong>LOGIC</strong></td><td>Dropdown</td><td>Logical connector and parenthesis grouping for combining multiple condition rows.</td></tr><tr><td><strong>ACTION</strong></td><td>Delete Button</td><td>Red trash icon to remove the condition row.</td></tr></tbody></table><hr><h2 id="operators" tabindex="-1">Condition Operator Reference <a class="header-anchor" href="#operators" aria-label="Permalink to “Condition Operator Reference”">​</a></h2><h3 id="_1-comparison-operators-comp" tabindex="-1">1. Comparison Operators (<code>COMP</code>) <a class="header-anchor" href="#_1-comparison-operators-comp" aria-label="Permalink to “1. Comparison Operators (COMP)”">​</a></h3><p>Controls how the target field&#39;s actual result is compared against your configured criteria:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Operator</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td style="text-align:center;"><code>==</code></td><td>Equal</td><td>Evaluates to true only if the actual field status/message exactly matches the criteria.</td></tr><tr><td style="text-align:center;"><code>!=</code></td><td>Not Equal</td><td>Evaluates to true if the actual field status/message differs from the criteria.</td></tr></tbody></table><h3 id="_2-status-options-status" tabindex="-1">2. Status Options (<code>STATUS</code>) <a class="header-anchor" href="#_2-status-options-status" aria-label="Permalink to “2. Status Options (STATUS)”">​</a></h3><p>Evaluates the boolean execution result of the target field:</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th><th>When to Use</th></tr></thead><tbody><tr><td><code>- Status</code></td><td>Unset / Ignored</td><td>Bypasses boolean checking when you only want to match the status message text.</td></tr><tr><td><code>true</code></td><td>Action Succeeded</td><td>Verifies that the target field executed without errors or element lookup failures.</td></tr><tr><td><code>false</code></td><td>Action Failed</td><td>Verifies that the target field failed, timed out, or threw an error.</td></tr></tbody></table><h3 id="_3-logical-operators-grouping-logic" tabindex="-1">3. Logical Operators &amp; Grouping (<code>LOGIC</code>) <a class="header-anchor" href="#_3-logical-operators-grouping-logic" aria-label="Permalink to “3. Logical Operators &amp; Grouping (LOGIC)”">​</a></h3><p>Connects sequential condition rows to form compound logical expressions:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Operator</th><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td style="text-align:center;"><code>&amp;&amp;</code></td><td>AND</td><td>Both the current condition and the next condition must be true.</td></tr><tr><td style="text-align:center;">`</td><td></td><td>`</td></tr><tr><td style="text-align:center;"><code>&amp;&amp; (</code></td><td>AND (Open Group)</td><td>Combines with the next condition using AND, beginning a nested parenthesis group.</td></tr><tr><td style="text-align:center;">`</td><td></td><td>(`</td></tr><tr><td style="text-align:center;"><code>)</code></td><td>Close Group</td><td>Closes the current nested parenthesis group.</td></tr></tbody></table><hr><h2 id="response-actions" tabindex="-1">Configuring Response Actions <a class="header-anchor" href="#response-actions" aria-label="Permalink to “Configuring Response Actions”">​</a></h2><p>After setting up your condition criteria, scroll to <strong>Response Action Settings</strong> in the field panel to define what happens based on the outcome:</p><h3 id="success-response-action" tabindex="-1">1. Field Success Response Action <a class="header-anchor" href="#success-response-action" aria-label="Permalink to “1. Field Success Response Action”">​</a></h3><p>Fires when your combined condition rules evaluate to <strong>true</strong>:</p><ul><li><strong>Execute Segment</strong>: Run a specific sub-routine or sequence (e.g., submitting the form or handling an optional step).</li><li><strong>Click on Element</strong>: Click a confirmation, submit, or proceed button.</li><li><strong>Go to Next Entry</strong>: Advance to the next data row in your uploaded <code>.xlsx</code> file.</li><li><strong>Open a URL</strong>: Navigate to the next URL in your multi-step flow.</li></ul><h3 id="error-response-action" tabindex="-1">2. Field Error Response Action <a class="header-anchor" href="#error-response-action" aria-label="Permalink to “2. Field Error Response Action”">​</a></h3><p>Fires when your combined condition rules evaluate to <strong>false</strong>:</p><ul><li><strong>Skip Form</strong>: Bypass remaining fields in the current form and transition to the next step.</li><li><strong>Stop Loop</strong>: Immediately halt repetitive loops when unexpected results occur.</li><li><strong>Execute Segment</strong>: Run a recovery routine (e.g., clear inputs, solve fallback authentication, or log errors).</li><li><strong>Reload Page</strong>: Refresh the page to reset form state and attempt execution again.</li></ul><hr><h2 id="examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Practical Examples”">​</a></h2><h3 id="example-1-verify-critical-fields-before-submitting" tabindex="-1">Example 1: Verify Critical Fields Before Submitting <a class="header-anchor" href="#example-1-verify-critical-fields-before-submitting" aria-label="Permalink to “Example 1: Verify Critical Fields Before Submitting”">​</a></h3><p>Ensure that both a primary input field and a file upload completed successfully before clicking the submit button:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Row</th><th>FIELD NAME</th><th style="text-align:center;">COMP</th><th style="text-align:center;">STATUS</th><th>MESSAGE</th><th style="text-align:center;">LOGIC</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><code>Candidate Email</code></td><td style="text-align:center;"><code>==</code></td><td style="text-align:center;"><code>true</code></td><td><em>(empty)</em></td><td style="text-align:center;"><code>&amp;&amp;</code></td></tr><tr><td style="text-align:center;">2</td><td><code>Resume Attachment</code></td><td style="text-align:center;"><code>==</code></td><td style="text-align:center;"><code>true</code></td><td><em>(empty)</em></td><td style="text-align:center;"><em>(empty)</em></td></tr></tbody></table><ul><li><strong>Success Response Action</strong>: <code>Click on Element</code> targeting <code>#submit-application-btn</code>.</li><li><strong>Error Response Action</strong>: <code>Execute Segment</code> targeting a notification segment alerting that required fields are missing.</li></ul><hr><h3 id="example-2-fallback-branching-on-failed-lookup" tabindex="-1">Example 2: Fallback Branching on Failed Lookup <a class="header-anchor" href="#example-2-fallback-branching-on-failed-lookup" aria-label="Permalink to “Example 2: Fallback Branching on Failed Lookup”">​</a></h3><p>If an automated address lookup failed, branch to a manual fallback segment:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Row</th><th>FIELD NAME</th><th style="text-align:center;">COMP</th><th style="text-align:center;">STATUS</th><th>MESSAGE</th><th style="text-align:center;">LOGIC</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><code>Auto Fill Address API</code></td><td style="text-align:center;"><code>==</code></td><td style="text-align:center;"><code>false</code></td><td><em>(empty)</em></td><td style="text-align:center;"><em>(empty)</em></td></tr></tbody></table><ul><li><strong>Success Response Action</strong>: <code>Execute Segment</code> targeting <code>Manual Address Fallback</code>.</li><li><strong>Error Response Action</strong>: Do nothing (continue normal workflow).</li></ul><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ul><li><strong>Field Sequence Order</strong>: Always place <strong>Field Action Status Checker</strong> <strong>below</strong> the fields it is inspecting. A field must finish execution before its outcome can be checked.</li><li><strong>Field Name Precision</strong>: Ensure the name entered in the <strong>FIELD NAME</strong> column matches the exact label or title configured on the target field.</li><li><strong>Parentheses Balance</strong>: When using grouping operators (<code>&amp;&amp; (</code> or <code>|| (</code>), ensure every opening parenthesis has a corresponding closing parenthesis <code>)</code> to prevent evaluation syntax errors.</li></ul>',47)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};